import json
import requests
import chardet
# Constants
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    """
    Fetches data from a specified REST API URL and processes it for JSON parsing.
    The process involves decoding and re-encoding the data, handling different encoding scenarios.

    Parameters:
    - url (str): The API URL to fetch data from. Defaults to API_URL.
    - from_encoding (str, optional): The encoding to use for decoding the response content. 
                                     If None, encoding is detected automatically.
    - to_encoding (str): The encoding to use for re-encoding the decoded content. Defaults to "utf8".

    Returns:
    - dict: The JSON-parsed data after re-encoding. Returns an empty dictionary if the content is empty.

    Raises:
    - ValueError: If unable to detect encoding for non-empty content.
    """
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        content = response.content
    except requests.exceptions.RequestException as e:
        raise Exception(f"Request failed: {e}")

    if not content:
        return {}

    if from_encoding is None:
        detected_encoding = chardet.detect(content)
        if detected_encoding['confidence'] > 0.5:
            from_encoding = detected_encoding['encoding']
        else:
            raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded_content = content.decode(from_encoding)
    except UnicodeDecodeError:
        raise ValueError(f"Failed to decode content with encoding: {from_encoding}")

    try:
        re_encoded_content = decoded_content.encode(to_encoding)
    except UnicodeEncodeError:
        raise ValueError(f"Failed to encode content to encoding: {to_encoding}")

    try:
        json_data = json.loads(re_encoded_content)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON: {e}")

    return json_data

import re
import requests
import json

def task_func(input):
    # Extract API endpoint from the input string using regex
    pattern = r'https?://[^\s/$.?#].[^\s]*'
    match = re.search(pattern, input)
    if not match:
        return {"error": "No valid API endpoint found in the input string"}

    endpoint = match.group(0)

    try:
        # Send GET request to the endpoint
        response = requests.get(endpoint)
        response.raise_for_status()  # Raise an exception for bad status codes

        # Try to parse the response as JSON
        try:
            data = response.json()
        except json.JSONDecodeError:
            # If response is not JSON, return as text
            data = {"response": response.text}

        return data

    except requests.exceptions.RequestException as e:
        return {"error": f"Request failed: {str(e)}"}

from flask import Flask
from flask_restful import Resource, Api
import requests

def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPIResource(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.exceptions.RequestException as e:
                return {'error': f'Failed to fetch data from external API: {str(e)}'}, 500

    api.add_resource(ExternalAPIResource, '/api/data')

    return app
